import{_ as e,c as t,o as i,a5 as l}from"./chunks/framework.DorIfSpC.js";const u=JSON.parse('{"title":"從零開始搞懂 GitHub 協作：開源新手必讀的名詞大全","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/project/github-collaboration-blog"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/project/github-collaboration-blog"}],["meta",{"property":"og:title","content":"從零開始搞懂 GitHub 協作：開源新手必讀的名詞大全 | 星智未來"}],["meta",{"name":"twitter:title","content":"從零開始搞懂 GitHub 協作：開源新手必讀的名詞大全 | 星智未來"}],["meta",{"property":"og:type","content":"article"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"從零開始搞懂 GitHub 協作：開源新手必讀的名詞大全\\",\\"description\\":\\"\\",\\"url\\":\\"https://blog.aidream.com.tw/project/github-collaboration-blog\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"url\\":\\"https://blog.aidream.com.tw\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"星智未來\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://blog.aidream.com.tw/logo.svg\\"}},\\"mainEntityOfPage\\":{\\"@type\\":\\"WebPage\\",\\"@id\\":\\"https://blog.aidream.com.tw/project/github-collaboration-blog\\"}}"]]},"headers":[],"relativePath":"project/github-collaboration-blog.md","filePath":"project/github-collaboration-blog.md","lastUpdated":1788355070000}'),s={name:"project/github-collaboration-blog.md"};function o(r,a,h,n,p,d){return i(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="從零開始搞懂-github-協作-開源新手必讀的名詞大全" tabindex="-1">從零開始搞懂 GitHub 協作：開源新手必讀的名詞大全 <a class="header-anchor" href="#從零開始搞懂-github-協作-開源新手必讀的名詞大全" aria-label="Permalink to &quot;從零開始搞懂 GitHub 協作：開源新手必讀的名詞大全&quot;">​</a></h1><blockquote><p>第一次想在 GitHub 上貢獻程式碼，卻被一堆術語搞得暈頭轉向？這篇文章幫你一次搞懂所有核心概念。</p></blockquote><p><strong>作者</strong>：Ray <strong>日期</strong>：2025 年 12 月 17 日</p><hr><p>剛接觸 GitHub 的時候，我也被這些術語搞得很困惑。Fork 是什麼？PR 又是什麼？為什麼要 rebase？這篇文章把我當初希望有人告訴我的東西，全部整理出來。</p><h2 id="先搞懂最基本的-你的程式碼住在哪裡" tabindex="-1">先搞懂最基本的：你的程式碼住在哪裡？ <a class="header-anchor" href="#先搞懂最基本的-你的程式碼住在哪裡" aria-label="Permalink to &quot;先搞懂最基本的：你的程式碼住在哪裡？&quot;">​</a></h2><h3 id="repository-repo" tabindex="-1">Repository (Repo) <a class="header-anchor" href="#repository-repo" aria-label="Permalink to &quot;Repository (Repo)&quot;">​</a></h3><p>簡單說，就是你的專案資料夾，但它不只是資料夾——它記住了你每一次的修改歷史。誰改的、什麼時候改的、改了什麼，全部都有紀錄。</p><p>你可以把它想像成一個有「時光機」功能的資料夾。</p><h3 id="clone" tabindex="-1">Clone <a class="header-anchor" href="#clone" aria-label="Permalink to &quot;Clone&quot;">​</a></h3><p>把雲端的 repo 下載到你的電腦上。這樣你就能在本機開發，不用一直連網。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/username/repo-name.git</span></span></code></pre></div><h3 id="fork" tabindex="-1">Fork <a class="header-anchor" href="#fork" aria-label="Permalink to &quot;Fork&quot;">​</a></h3><p>這是開源協作的第一步。</p><p>當你想貢獻別人的專案，你不能直接改人家的程式碼（想想也知道這樣會亂套）。所以你先把整個專案「複製」一份到你自己的帳號下，這個動作就叫 Fork。</p><p>Fork 出來的是你的副本，你可以隨便改，不會影響原本的專案。改好之後，再透過 Pull Request 請求合併回去。</p><hr><h2 id="版本控制的基本動作" tabindex="-1">版本控制的基本動作 <a class="header-anchor" href="#版本控制的基本動作" aria-label="Permalink to &quot;版本控制的基本動作&quot;">​</a></h2><h3 id="branch-分支" tabindex="-1">Branch（分支） <a class="header-anchor" href="#branch-分支" aria-label="Permalink to &quot;Branch（分支）&quot;">​</a></h3><p>想像你在寫一份報告，但你想試試看另一種寫法。你會怎麼做？複製一份出來改，對吧？</p><p>Branch 就是這個概念。你從主線（通常叫 <code>main</code> 或 <code>master</code>）岔出去，開一條新的線來開發新功能。這樣即使你改壞了，主線還是安全的。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature/new-feature</span></span></code></pre></div><h3 id="commit" tabindex="-1">Commit <a class="header-anchor" href="#commit" aria-label="Permalink to &quot;Commit&quot;">​</a></h3><p>每次你覺得「好，這個階段可以存檔了」，就做一次 commit。它會記錄：</p><ul><li>你改了哪些檔案</li><li>什麼時候改的</li><li>你是誰</li><li>你為什麼改（commit message）</li></ul><p>寫好 commit message 很重要。三個月後的你會感謝現在的你。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修正登入頁面的驗證邏輯&quot;</span></span></code></pre></div><h3 id="push-pull" tabindex="-1">Push &amp; Pull <a class="header-anchor" href="#push-pull" aria-label="Permalink to &quot;Push &amp; Pull&quot;">​</a></h3><ul><li><strong>Push</strong>：把你本機的修改上傳到遠端（GitHub）</li><li><strong>Pull</strong>：把遠端的更新下載到本機</li></ul><p>這兩個動作讓你的本機和雲端保持同步。</p><hr><h2 id="協作的核心-pull-request" tabindex="-1">協作的核心：Pull Request <a class="header-anchor" href="#協作的核心-pull-request" aria-label="Permalink to &quot;協作的核心：Pull Request&quot;">​</a></h2><h3 id="pull-request-pr" tabindex="-1">Pull Request (PR) <a class="header-anchor" href="#pull-request-pr" aria-label="Permalink to &quot;Pull Request (PR)&quot;">​</a></h3><p>這是開源協作的靈魂。</p><p>當你在自己的 fork 上改好程式碼後，你會發一個「請求」給原專案，說：「嘿，我改了這些東西，你們要不要收？」</p><p>這個請求就是 Pull Request。</p><p>PR 不只是提交程式碼，它還是討論的地方。維護者可能會問你為什麼這樣改、建議你調整某些地方，你們來回討論，直到大家都滿意，才會 merge。</p><h3 id="merge" tabindex="-1">Merge <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;Merge&quot;">​</a></h3><p>把一個分支的修改合併到另一個分支。當你的 PR 被接受，維護者就會把你的程式碼 merge 進主線。</p><p>恭喜，你成為這個專案的 contributor 了！</p><h3 id="code-review" tabindex="-1">Code Review <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;Code Review&quot;">​</a></h3><p>在 merge 之前，通常會有人幫你看程式碼，這就是 Code Review。</p><p>不要害怕 review，這是學習的好機會。好的 reviewer 會告訴你為什麼要這樣改，而不只是說「這樣不行」。</p><hr><h2 id="issue-專案的討論區" tabindex="-1">Issue：專案的討論區 <a class="header-anchor" href="#issue-專案的討論區" aria-label="Permalink to &quot;Issue：專案的討論區&quot;">​</a></h2><h3 id="issue-是什麼" tabindex="-1">Issue 是什麼？ <a class="header-anchor" href="#issue-是什麼" aria-label="Permalink to &quot;Issue 是什麼？&quot;">​</a></h3><p>Issue 是 GitHub 內建的討論系統。你可以用它來：</p><ul><li>回報 bug：「這個按鈕點了沒反應」</li><li>提出新功能：「希望可以支援深色模式」</li><li>問問題：「請問這個函數是做什麼用的？」</li></ul><p>每個 issue 都有編號，你可以在 commit 或 PR 中引用它。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;修正登入問題 #42&quot;</span></span></code></pre></div><p>這樣 GitHub 會自動把這個 commit 連結到 issue #42。</p><h3 id="labels" tabindex="-1">Labels <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;Labels&quot;">​</a></h3><p>用來分類 issue 的標籤。常見的有：</p><table tabindex="0"><thead><tr><th>Label</th><th>意思</th></tr></thead><tbody><tr><td><code>bug</code></td><td>程式錯誤</td></tr><tr><td><code>enhancement</code></td><td>新功能或改進</td></tr><tr><td><code>documentation</code></td><td>文件相關</td></tr><tr><td><code>good first issue</code></td><td>適合新手的任務</td></tr><tr><td><code>help wanted</code></td><td>需要協助</td></tr></tbody></table><p><strong>小技巧</strong>：想開始貢獻開源？搜尋 <code>good first issue</code> 標籤，這些通常是維護者特別挑出來給新手練手的。</p><hr><h2 id="自動化-讓機器幫你把關" tabindex="-1">自動化：讓機器幫你把關 <a class="header-anchor" href="#自動化-讓機器幫你把關" aria-label="Permalink to &quot;自動化：讓機器幫你把關&quot;">​</a></h2><h3 id="ci-cd" tabindex="-1">CI/CD <a class="header-anchor" href="#ci-cd" aria-label="Permalink to &quot;CI/CD&quot;">​</a></h3><p>全名是 Continuous Integration / Continuous Deployment，中文叫持續整合與部署。</p><p>簡單說，就是每次有人提交程式碼，機器會自動：</p><ol><li>跑測試，確保沒有東西壞掉</li><li>檢查程式碼風格</li><li>甚至自動部署到伺服器</li></ol><p>這樣就不用人工一個一個檢查，省時又不會漏掉。</p><h3 id="github-actions" tabindex="-1">GitHub Actions <a class="header-anchor" href="#github-actions" aria-label="Permalink to &quot;GitHub Actions&quot;">​</a></h3><p>GitHub 內建的自動化工具。你可以設定：</p><ul><li>每次 push 就跑測試</li><li>每次發 PR 就檢查程式碼風格</li><li>每天定時執行某些任務</li></ul><p>設定檔放在 <code>.github/workflows/</code> 資料夾裡。</p><h3 id="linter" tabindex="-1">Linter <a class="header-anchor" href="#linter" aria-label="Permalink to &quot;Linter&quot;">​</a></h3><p>自動檢查程式碼風格的工具。它會告訴你：</p><ul><li>縮排不對</li><li>變數沒用到</li><li>命名不符合規範</li></ul><p>很煩，但很有用。統一的風格讓程式碼更容易維護。</p><hr><h2 id="專案必備的文件" tabindex="-1">專案必備的文件 <a class="header-anchor" href="#專案必備的文件" aria-label="Permalink to &quot;專案必備的文件&quot;">​</a></h2><p>一個好的開源專案，通常會有這些文件：</p><h3 id="readme-md" tabindex="-1">README.md <a class="header-anchor" href="#readme-md" aria-label="Permalink to &quot;README.md&quot;">​</a></h3><p>專案的門面。訪客第一眼看到的就是這個。</p><p>好的 README 要包含：</p><ul><li>專案是做什麼的</li><li>怎麼安裝</li><li>怎麼使用</li><li>簡單的範例</li></ul><h3 id="contributing-md" tabindex="-1">CONTRIBUTING.md <a class="header-anchor" href="#contributing-md" aria-label="Permalink to &quot;CONTRIBUTING.md&quot;">​</a></h3><p>貢獻指南。告訴想參與的人：</p><ul><li>怎麼設定開發環境</li><li>怎麼提交 PR</li><li>commit message 要怎麼寫</li><li>程式碼風格要求</li></ul><h3 id="license" tabindex="-1">LICENSE <a class="header-anchor" href="#license" aria-label="Permalink to &quot;LICENSE&quot;">​</a></h3><p>授權條款。這個很重要！</p><p>沒有 LICENSE 的專案，別人在法律上是不能用的。常見的授權：</p><table tabindex="0"><thead><tr><th>授權</th><th>特性</th></tr></thead><tbody><tr><td>MIT</td><td>最寬鬆，幾乎可以做任何事</td></tr><tr><td>Apache 2.0</td><td>類似 MIT，但有專利保護</td></tr><tr><td>GPL</td><td>衍生作品也必須開源</td></tr></tbody></table><h3 id="code-of-conduct-md" tabindex="-1">CODE_OF_CONDUCT.md <a class="header-anchor" href="#code-of-conduct-md" aria-label="Permalink to &quot;CODE_OF_CONDUCT.md&quot;">​</a></h3><p>行為準則。定義社群的互動規範，讓大家知道什麼行為是被接受的、什麼不是。</p><hr><h2 id="進階概念-當你開始深入協作" tabindex="-1">進階概念：當你開始深入協作 <a class="header-anchor" href="#進階概念-當你開始深入協作" aria-label="Permalink to &quot;進階概念：當你開始深入協作&quot;">​</a></h2><h3 id="upstream-vs-origin" tabindex="-1">Upstream vs Origin <a class="header-anchor" href="#upstream-vs-origin" aria-label="Permalink to &quot;Upstream vs Origin&quot;">​</a></h3><p>這兩個詞常常讓人搞混：</p><ul><li><strong>Origin</strong>：你自己的遠端 repo（通常是你 fork 的那份）</li><li><strong>Upstream</strong>：原始專案的 repo</li></ul><p>當原專案更新了，你需要從 upstream 同步最新的程式碼到你的 fork。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream/main</span></span></code></pre></div><h3 id="conflict-衝突" tabindex="-1">Conflict（衝突） <a class="header-anchor" href="#conflict-衝突" aria-label="Permalink to &quot;Conflict（衝突）&quot;">​</a></h3><p>當兩個人改了同一段程式碼，Git 不知道該用誰的版本，這就產生了衝突。</p><p>你需要手動決定要保留哪個版本，或者合併兩者。這是協作中最讓人頭痛的部分，但也是必經之路。</p><h3 id="rebase" tabindex="-1">Rebase <a class="header-anchor" href="#rebase" aria-label="Permalink to &quot;Rebase&quot;">​</a></h3><p>把你的 commits「搬」到另一個分支的最新點上。</p><p>跟 merge 的差別是：rebase 會讓 commit 歷史更乾淨、更線性，但操作比較複雜，搞錯了會很麻煩。</p><p>新手建議先用 merge，熟了再學 rebase。</p><h3 id="squash" tabindex="-1">Squash <a class="header-anchor" href="#squash" aria-label="Permalink to &quot;Squash&quot;">​</a></h3><p>把多個 commits 壓成一個。</p><p>有時候你開發過程中 commit 了很多次（「修 bug」「真的修好了」「這次真的」），squash 可以把它們合成一個乾淨的 commit。</p><hr><h2 id="標準協作流程-從頭到尾走一遍" tabindex="-1">標準協作流程：從頭到尾走一遍 <a class="header-anchor" href="#標準協作流程-從頭到尾走一遍" aria-label="Permalink to &quot;標準協作流程：從頭到尾走一遍&quot;">​</a></h2><ol><li><strong>Fork</strong> 原專案到自己帳號</li><li><strong>Clone</strong> 到本機</li><li>建立新 <strong>Branch</strong></li><li>修改程式碼並 <strong>Commit</strong></li><li><strong>Push</strong> 到自己的 Fork</li><li>發起 <strong>Pull Request</strong></li><li>等待 <strong>Code Review</strong></li><li>根據回饋修改或討論</li><li><strong>Merge</strong> 完成！</li></ol><hr><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>GitHub 協作一開始確實有點門檻，術語多、流程也要習慣。但一旦搞懂這些概念，你會發現開源世界其實很友善。</p><p>不要怕犯錯，每個人都是從新手開始的。找一個 <code>good first issue</code>，發你的第一個 PR，開始你的開源之旅吧！</p>`,110)])])}const b=e(s,[["render",o]]);export{u as __pageData,b as default};
